Optimize the linear scans in `validateFixtureCase` by mapping lookup keys to a Set beforehand. This reduces the complexity of validation checks from O(N * M) to O(N + M), preventing performance bottlenecks as the number of assertions and fixture elements grows.

```javascript
function validateFixtureCase(fixture) {
  const failureCodes = new Set();

  const partIds = new Set((fixture.question_parts ?? []).map((p) => p.question_part_id));
  const procInstIds = new Set((fixture.procedure_instances ?? []).map((p) => p.procedure_instance_id));
  const procStepIds = new Set((fixture.procedure_step_instances ?? []).map((p) => p.procedure_step_instance_id));
  const markStepIds = new Set((fixture.mark_step_refs ?? []).map((p) => p.mark_step_ref_id));
  const markAwardIds = new Set((fixture.mark_award_refs ?? []).map((p) => p.mark_award_ref_id));

  const setsByScope = {
    question_part: partIds,
    procedure_instance: procInstIds,
    procedure_step_instance: procStepIds,
    mark_step_reference: markStepIds,
    mark_award_reference: markAwardIds,
  };

  for (const assertion of fixture.semantic_assertions ?? []) {
    if (!ALLOWED_SCOPE_LEVELS.includes(assertion.scope_level)) {
      failureCodes.add('semantic_assertion_scope_level_not_allowed');
    }
    const hasRef = assertion.scope_level === 'whole_question'
      ? assertion.scope_ref_id === fixture.question_row_id
      : (setsByScope[assertion.scope_level]?.has(assertion.scope_ref_id) ?? false);
    if (!hasRef) {
      failureCodes.add('semantic_assertion_scope_ref_missing');
    }
    if (!Array.isArray(assertion.evidence_refs) || assertion.evidence_refs.length === 0) {
      failureCodes.add('semantic_assertion_evidence_refs_required');
    }
    if (assertion.scope_level === 'whole_question') {
      if (
        !WHOLE_QUESTION_JUSTIFICATIONS.includes(assertion.whole_question_justification_code)
        || !hasAllPartSupport(fixture, assertion)
      ) {
        failureCodes.add('whole_question_scope_requires_allowed_justification');
      }
    }
    if (
      assertion.scope_level === 'mark_step_reference'
      || assertion.scope_level === 'mark_award_reference'
    ) {
      failureCodes.add('mark_reference_must_not_be_semantic_assertion_subject');
    }
  }

  if (!profilePreservesProvenance(fixture.question_semantic_profile)) {
    failureCodes.add('profile_aggregation_must_preserve_scope_provenance');
  }

  if ((fixture.procedure_step_instances ?? []).some((step) => step.derived_from_mark_label === true)) {
    failureCodes.add('mark_label_must_not_define_semantic_step');
  }
  if ((fixture.mark_step_refs ?? []).some((markStep) => markStep.semantic_step === true)) {
    failureCodes.add('mark_label_must_not_define_semantic_step');
  }

  for (const markStep of fixture.mark_step_refs ?? []) {
    if (
      markStep.attached_scope_level === 'procedure_step_instance'
      && !procStepIds.has(markStep.attached_scope_ref_id)
    ) {
      failureCodes.add('mark_step_ref_attachment_target_missing');
    }
    if (!Array.isArray(markStep.source_artifact_refs) || markStep.source_artifact_refs.length === 0) {
      failureCodes.add('mark_step_ref_source_artifact_refs_required');
    }
  }

  for (const group of fixture.alternative_method_groups ?? []) {
    if ((group.procedure_instance_ids ?? []).length < group.viable_branch_count) {
      failureCodes.add('alternative_methods_must_not_collapse_branch_instances');
    }
    for (const procedureInstanceId of group.procedure_instance_ids ?? []) {
      if (!procInstIds.has(procedureInstanceId)) {
        failureCodes.add('alternative_method_group_ref_missing_procedure_instance');
      }
    }
  }

  return [...failureCodes].sort(compareByteOrder);
}
